WITH exploded AS (SELECT id, effective_from, element FROM price_tiers LATERAL VIEW EXPLODE(discounts) e AS element), scored AS (SELECT *, DENSE_RANK() OVER (ORDER BY element DESC) AS element_dense_rank FROM exploded), base AS (SELECT *, element + element_dense_rank AS element_plus_element_dense_rank FROM scored WHERE element > 33), cleaned AS (SELECT *, CASE WHEN element_dense_rank >= 9 THEN 'High' WHEN element_dense_rank >= 4 THEN 'Medium' ELSE 'Low' END AS element_dense_rank_band, GREATEST(element, element_plus_element_dense_rank) AS greatest_element_element_plus_element_dense_rank FROM base WHERE element_dense_rank <= 8) SELECT effective_from, element, element_dense_rank, element_plus_element_dense_rank, element_dense_rank_band, greatest_element_element_plus_element_dense_rank FROM cleaned ORDER BY element_plus_element_dense_rank DESC NULLS LAST;
